using System.Text.Json.Nodes;
namespace RisingLands;
public static class ImprovementsV71Tests {
 static int checks;
 static void Check(bool ok,string name){checks++;if(!ok)throw new Exception("FAIL v71: "+name);Console.WriteLine("PASS v71: "+name);}
 static void Until(Simulation s,Func<bool> done,int limit=12000){for(int i=0;i<limit&&!done();i++)s.Step();Check(done(),"bounded simulation completes");}
 static void Reload(Simulation s,Simulation copy){string before=s.Serialize();copy.Restore(before);Check(copy.Serialize()==before,"state roundtrip");for(int i=0;i<20;i++){s.Step();copy.Step();}Check(copy.Serialize()==s.Serialize(),"deterministic continuation");}
 static Simulation TradeFixture(string root){return TradeV97Tests.Fixture(root);}
 public static void Run(string root){
  var s=ImprovementsV67Tests.Fixture(root);var builder=s.World.Units.First(a=>a.Type==7&&a.Owner==0);for(int i=0;i<4;i++)while(s.GrantTestTechnology(i)){}for(int i=0;i<20;i++)foreach(int k in new[]{0,1,2})s.GrantTestResource(k);
  int anchor=40+40*256;
  for(int mask=0;mask<16;mask++){s=ImprovementsV67Tests.Fixture(root);s.World.Buildings.Add(new(950,9,0,anchor));int slot=951;foreach(var (bit,offset) in new[]{(1,-256),(2,1),(4,256),(8,-1)})if((mask&bit)!=0)s.World.Buildings.Add(new(slot++,9,0,anchor+offset));Check(s.WallMask(anchor)==mask,"native neighbour mask "+mask);Check(!s.Passable(40,40),"wall remains blocked "+mask);}
  foreach(var b in s.World.Buildings.Where(b=>b.Slot>=950).ToArray())s.World.Buildings.Remove(b);
  foreach(var (dx,dy) in new[]{(0,-1),(1,0),(0,1),(-1,0)})s.World.Buildings.Add(new(950+s.World.Buildings.Count,9,0,anchor+dy*256+dx));
  var unit=s.World.Units.First(a=>a.Type==0&&a.Owner==0);unit.X=unit.Y=40*1024;Check(!s.Order(unit,42,40),"enclosed troop cannot cross wall");unit.Type=16;Check(s.Order(unit,42,40),"airborne troop flies over enclosing walls");unit.Type=0;
  Check(Simulation.WallLine(10+10*256,13+12*256).Length==6,"dragged line is continuous at corners");
  s=ImprovementsV67Tests.Fixture(root);builder=s.World.Units.First(a=>a.Type==7&&a.Owner==0);for(int i=0;i<4;i++)while(s.GrantTestTechnology(i)){}for(int i=0;i<20;i++)foreach(int k in new[]{0,1,2})s.GrantTestResource(k);builder.X=39*1024;builder.Y=40*1024;Check(s.PlanWall(builder,anchor,anchor+4)==5,"five wall sites queued in one order");string pending=s.Serialize();var clone=ImprovementsV67Tests.Fixture(root);clone.Restore(pending);Check(clone.Serialize()==pending,"wall queue survives save/load");Until(s,()=>s.Constructions.All(s.Complete));Check(s.World.Buildings.Count(b=>b.Type==9)==5&&s.Special.WallPlans.Count==0,"builder completes continuous wall queue");
  var t=TradeFixture(root);var messenger=SpecialV66Tests.Recruit(t,10);var market=t.World.Buildings.First(b=>b.Type==16&&b.Owner==1);Check(t.SendMessenger(messenger,market.Slot),"messenger travels to enemy market");Until(t,()=>t.NegotiationFor(1)?.Stage=="Ready");var n=t.NegotiationFor(1)!;Check(!VisualCatalog.Visible(messenger),"arrived messenger is inside market");Reload(t,TradeFixture(root));int food=t.World.Resources[0],rock=t.World.Resources[4];Check(t.SubmitTrade(n,new[]{10,0,0},new[]{0,8,0}),"submit weighted neutral offer");Check(t.World.Resources[0]==food&&t.World.Resources[4]==rock,"evaluation does not debit stocks");Reload(t,TradeFixture(root));Until(t,()=>!n.Active);Check(n.Stage=="Completed"&&t.World.Resources[0]<=food-10&&t.World.Resources[4]==rock+8,"accepted offer transfers material directly");Reload(t,TradeFixture(root));
  var bad=JsonNode.Parse(t.Serialize())!;bad["Special"]!["UnitExchanges"]!.AsArray().Add(new JsonObject{["Slot"]=messenger.Slot,["From"]=0,["To"]=1,["Tick"]=t.Tick});string before=t.Serialize();try{t.Restore(bad.ToJsonString());throw new Exception("Forged ownership accepted");}catch(InvalidDataException){}Check(t.Serialize()==before,"forged ownership transfer rejected atomically");
  t=TradeFixture(root);messenger=SpecialV66Tests.Recruit(t,10);market=t.World.Buildings.First(b=>b.Type==16&&b.Owner==1);Check(t.SendMessenger(messenger,market.Slot),"second negotiation begins");Until(t,()=>t.NegotiationFor(1)?.Stage=="Ready");n=t.NegotiationFor(1)!;Check(t.SubmitTrade(n,new[]{1,0,0},new[]{0,100,0}),"unfair offer is evaluated");food=t.World.Resources[0];Until(t,()=>!n.Active);Check(n.Stage=="Rejected"&&t.Special.Trades.Count==0,"unfair offer rejected without transaction");
  t=TradeFixture(root);messenger=SpecialV66Tests.Recruit(t,10);market=t.World.Buildings.First(b=>b.Type==16&&b.Owner==1);Check(t.SendMessenger(messenger,market.Slot),"unit negotiation begins");Until(t,()=>t.NegotiationFor(1)?.Stage=="Ready");n=t.NegotiationFor(1)!;var enemy=t.TradeUnits(1).First();Check(t.SubmitTrade(n,new[]{100,0,0},new int[3],takeUnits:new[]{enemy.Slot}),"offer can request eligible troop");Until(t,()=>!n.Active);Check(n.Stage=="Completed"&&enemy.Owner==0&&VisualCatalog.Visible(enemy),"received troop exits player Exchange");Reload(t,TradeFixture(root));
  Check(Enumerable.Range(0,26).Count(Simulation.UnitExchangeable)==18,"all tradeable classes including aircraft exclude colonists under v113 requirements");n=new(){Owner=1,Give=new[]{50,0,0},Take=new[]{0,50,0}};t.Campaign.Goodwill[1]=-60;Check(t.NegotiationScore(n)==20,"hostile goodwill reduces valuation");t.Campaign.Goodwill[1]=0;t.Campaign.Alliances[1]=true;Check(t.NegotiationScore(n)==120,"alliance improves valuation");
  t=TradeFixture(root);messenger=SpecialV66Tests.Recruit(t,10);market=t.World.Buildings.First(b=>b.Type==16&&b.Owner==1);Check(t.SendMessenger(messenger,market.Slot),"bilateral troop negotiation begins");Until(t,()=>t.NegotiationFor(1)?.Stage=="Ready");n=t.NegotiationFor(1)!;enemy=t.TradeUnits(1).First();var worker=t.TradeUnits(0).First(a=>a.Type==7);Check(t.SubmitTrade(n,new[]{3,0,0},new int[3],new[]{worker.Slot},new[]{enemy.Slot}),"trade can offer own builder and request enemy troop");Until(t,()=>n.Stage=="Delivery");Check(t.StoreTradeUnit(worker,t.Exchange(0)!),"player sends offered unit to own Exchange");Reload(t,TradeFixture(root));Until(t,()=>!n.Active);Check(n.Stage=="Completed"&&worker.Owner==1&&enemy.Owner==0,"bilateral actors exchange ownership once");Reload(t,TradeFixture(root));
  t=TradeFixture(root);messenger=SpecialV66Tests.Recruit(t,10);market=t.World.Buildings.First(b=>b.Type==16&&b.Owner==1);Check(t.SendMessenger(messenger,market.Slot),"timeout negotiation begins");Until(t,()=>t.NegotiationFor(1)?.Stage=="Ready");n=t.NegotiationFor(1)!;Until(t,()=>!n.Active);Check(n.Stage=="Cancelled"&&t.Special.Trades.Count==0,"negotiation timeout never moves resources");
  t=TradeFixture(root);messenger=SpecialV66Tests.Recruit(t,10);var visiting=System.Text.Json.JsonSerializer.Deserialize<Actor>(System.Text.Json.JsonSerializer.Serialize(messenger))!;visiting.Slot=t.World.Units.Max(a=>a.Slot)+1;visiting.Owner=1;t.World.Units.Add(visiting);t=new Simulation(t.World);Until(t,()=>t.NegotiationFor(1)?.Stage=="Incoming");n=t.NegotiationFor(1)!;Check(n.Incoming&&n.Give.Sum()>0,"enemy messenger opens received offer");Check(!t.SubmitTrade(n,new int[3],new[]{0,1,0}),"received request cannot be edited");t.CancelNegotiation(n);Check(n.Stage=="Cancelled","player can refuse received offer");
  t=TradeFixture(root);messenger=SpecialV66Tests.Recruit(t,10);market=t.World.Buildings.First(b=>b.Type==16&&b.Owner==1);var missing=t.Exchange(1)!;t.World.Buildings.Remove(missing);string unchanged=t.Serialize();Check(!t.SendMessenger(messenger,market.Slot)&&t.Serialize()==unchanged,"missing enemy Exchange rejects contact without changing orders");
  t=TradeFixture(root);messenger=SpecialV66Tests.Recruit(t,10);market=t.World.Buildings.First(b=>b.Type==16&&b.Owner==1);Check(t.SendMessenger(messenger,market.Slot),"unfulfilled delivery negotiation begins");Until(t,()=>t.NegotiationFor(1)?.Stage=="Ready");n=t.NegotiationFor(1)!;worker=t.TradeUnits(0).First(a=>a.Type==7);Check(t.SubmitTrade(n,new int[3],new[]{0,1,0},new[]{worker.Slot}),"own troop contract awaits explicit delivery");Until(t,()=>n.Stage=="Delivery");int goodwill=t.Goodwill(1);for(int i=0;i<2400;i++)t.Step();Check(n.Stage=="Delivery"&&t.Goodwill(1)==goodwill&&worker.Owner==0,"v100 accepted contract waits for class counts without timeout or troop loss");t.CancelNegotiation(n);Reload(t,TradeFixture(root));
  Console.WriteLine($"ALL v71 TESTS PASSED: {checks}");
 }
}

